"""Run /usr/bin/python3 tools/gen_update_labels.py (Pillow + Noto CJK)."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
font=ImageFont.truetype('/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc',22,index=2)
out=['/* SPDX-License-Identifier: OFL-1.1 */',
     '/* Generated by tools/gen_update_labels.py; 24x24, MSB first. Glyphs from Noto Sans CJK SC,\n * see LICENSES/OFL-1.1-Noto.txt. */',
     'static const uint8_t fw_glyphs[][72]={']
for ch in '允许拒绝升级回退':
    im=Image.new('1',(24,24));d=ImageDraw.Draw(im);a,b,c,e=d.textbbox((0,0),ch,font=font)
    d.text(((24-c+a)//2-a,(24-e+b)//2-b),ch,font=font,fill=1)
    out.append('  {'+','.join(map(str,im.tobytes()))+'},')
Path(__file__).resolve().parents[1].joinpath('ui/app_lcd_update_glyphs.inc').write_text('\n'.join(out+['};','']))
